contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _logger, bytes32 _txid) public payable {
        require(_logger != address(0));
        // fresh deployment: nobody is an approved logger yet
        bool beforeApproved = c.approvedToLog(_logger);
        uint256 r1 = c.logRedeemed(_txid);
        bool approvedAfterFail = c.approvedToLog(_logger);
        // non-owner (this test contract) cannot approve a logger
        bool reverted;
        try c.setApprovedLogger(_logger, true) { reverted = false; }
        catch { reverted = true; }
        bool stillApproved = c.approvedToLog(_logger);
        uint256 r2 = c.logRedeemed(_txid);
        assert(
            reverted &&
            !beforeApproved && !approvedAfterFail && !stillApproved &&
            r1 == false && r2 == false
        );
    }
    receive() external payable {}
}
